SELECT COUNT(*) FROM badges as b, posts as p, postLinks as pl, votes as v, users as u WHERE u.Id = p.OwnerUserId AND p.Id = pl.RelatedPostId AND u.Id = b.UserId AND u.Id = v.UserId AND p.AnswerCount>=0 AND p.FavoriteCount>=0 AND pl.LinkTypeId=1 AND v.CreationDate>=CAST('2010-07-20 00:00:00' AS TIMESTAMP)
